import re

def capitalize_words(text: str) -> str:
    """Upper-case the first character of every whitespace-separated word and lower-case
    the rest. Whitespace between words is preserved exactly.
    """
    def transform(match: str) -> str:
        word = match.group(0)
        if not word:
            return word
        return word[0].upper() + word[1:].lower()
    return re.sub(r'\S+', transform, text)

def dedupe_chars(text: str) -> str:
    """Return *text* with later occurrences of a character removed, keeping the first
    occurrence in place. The comparison is case sensitive.
    """
    seen = set()
    result = []
    for ch in text:
        if ch not in seen:
            seen.add(ch)
            result.append(ch)
    return ''.join(result)

def char_frequency(text: str) -> dict:
    """Return a dict mapping each non-whitespace character of *text* to how often it
    occurs. Case is significant.
    """
    freq = {}
    for ch in text:
        if not ch.isspace():
            freq[ch] = freq.get(ch, 0) + 1
    return freq

