def word_count(text: str) -> dict:
    """Count the whitespace-separated words of *text* case-insensitively, ignoring leading
    and trailing punctuation of each word (. , ! ? ; :).
    """
    punctuation = '.,!?:;'
    counts = {}
    for token in text.split():
        cleaned = token.strip(punctuation)
        lower = cleaned.lower()
        if lower:
            counts[lower] = counts.get(lower, 0) + 1
    return counts

