        return a
    else:
        return gcd_rec(b, a % b)

def binary_search(items: list, target) -> int:
    """Return the index of the FIRST occurrence of *target* in the sorted list *items*, or
    -1 when it is absent.
    """
    low = 0
    high = len(items)
    while low < high:
        mid = (low + high) // 2
        if items[mid] < target:
            low = mid + 1
        else:
            high = mid
    if low < len(items) and items[low] == target:
        return low
    return -1

